SELECT
h.id, h.instock_no, h.instock_date, h.supplier_id, NULL, h.total_amount, NULL, NULL, h.status, 0 FROM pur_instock h WHERE h.deleted = 0 AND h.id = #{id}
h.id, h.return_no, h.return_date, h.supplier_id, NULL, h.total_amount, NULL, NULL, h.status, 0 FROM pur_return h WHERE h.deleted = 0 AND h.id = #{id}
h.id, h.out_no, h.out_date, h.customer_id, NULL, h.total_amount, NULL, NULL, h.status, 0 FROM sal_outstock h WHERE h.deleted = 0 AND h.id = #{id}
h.id, h.return_no, h.return_date, h.customer_id, NULL, h.total_amount, NULL, NULL, h.status, 0 FROM sal_return h WHERE h.deleted = 0 AND h.id = #{id}
h.id, h.invoice_no, COALESCE(h.invoice_date, CURDATE()), h.customer_id, NULL, h.total_amount, h.tax_amount, h.amount, h.status, h.red_flag FROM inv_sales_invoice h WHERE h.deleted = 0 AND h.id = #{id}
h.id, h.invoice_no, COALESCE(h.auth_date, h.invoice_date, CURDATE()), h.supplier_id, NULL, h.total_amount, h.tax_amount, h.amount, h.status, h.red_flag FROM inv_purchase_invoice h WHERE h.deleted = 0 AND h.id = #{id}
h.id, h.receipt_no, h.biz_date, h.customer_id, h.account_id, h.amount, NULL, NULL, 10, 0 FROM fin_receipt h WHERE h.deleted = 0 AND h.id = #{id}
h.id, h.payment_no, h.biz_date, h.supplier_id, h.account_id, h.amount, NULL, NULL, 10, 0 FROM fin_payment h WHERE h.deleted = 0 AND h.id = #{id}
NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0 FROM DUAL WHERE 1 = 0

SELECT
d.qty, d.amount, d.tax_rate, NULL, NULL, NULL FROM pur_instock_detail d WHERE d.deleted = 0 AND d.instock_id = #{id}
d.qty, d.amount, d.tax_rate, NULL, NULL, NULL FROM pur_return_detail d WHERE d.deleted = 0 AND d.return_id = #{id}
d.qty, d.amount, 0, d.actual_cost, NULL, NULL FROM sal_outstock_detail d WHERE d.deleted = 0 AND d.out_id = #{id}
d.qty, d.amount, 0, NULL, od.qty, od.actual_cost FROM sal_return_detail d LEFT JOIN sal_outstock_detail od ON od.id = d.out_detail_id AND od.deleted = 0 WHERE d.deleted = 0 AND d.return_id = #{id}
NULL, NULL, 0, NULL, NULL, NULL FROM DUAL WHERE 1 = 0
